            bannerMessage = message
        }
        Task {
            try? await Task.sleep(for: .seconds(3))
            withAnimation(.easeOut(duration: Theme.Motion.fast)) {
                if self.bannerMessage == message {
                    self.bannerMessage = nil
                }
            }
        }
    }
}

